{
  "status": "Working notes. Include a trial in measured results only when its complete paired matrix and oracle exist. Decisions may change after combined verification.",
  "trials": [
    {
      "trial": 32,
      "title": "Stable generic-object routing",
      "hypothesis": "Cache repeated class dispatch only for providers that promise stable class information.",
      "decision": "Rejected: small/Blueprint/table regressions outweighed modest level gains."
    },
    {
      "trial": 33,
      "title": "Fuse replay construction and value decoding",
      "hypothesis": "Validate all headers, then construct and decode each record in one walk.",
      "decision": "Rejected: decoding a temporary record increased copies and slowed tables."
    },
    {
      "trial": 34,
      "title": "Prepare common scalar decisions",
      "hypothesis": "Attach scalar decoding plans to each validated layout, alongside temporary-record fusion.",
      "decision": "Rejected: planning did not offset the temporary-record cost."
    },
    {
      "trial": 35,
      "title": "Validate common leaf headers with fixed words",
      "hypothesis": "Compare all 24 stable leaf-header bytes and the current bool flag using safe integer loads.",
      "decision": "Retained as the common leaf-header validator in core1."
    },
    {
      "trial": 37,
      "title": "Decode in the final vector slot",
      "hypothesis": "Push the record before decoding so its value is written in its final location.",
      "decision": "Retained final-slot decoding as part of core1; not a useful independent winner."
    },
    {
      "trial": 38,
      "title": "Compact privately owned object paths",
      "hypothesis": "Use Box<str> inside the private ObjectPath representation while preserving its public methods.",
      "decision": "Not retained in core1: compatible private representation, but broader combinations regressed cold/level lanes."
    },
    {
      "trial": 39,
      "title": "Prepare scalars with separate construction and decoding walks",
      "hypothesis": "Keep ordinary two-pass ownership while reusing scalar plans.",
      "decision": "Not retained alone: weak aggregate benefit."
    },
    {
      "trial": 41,
      "title": "Cache complete struct-resolution facts",
      "hypothesis": "Memoize pure qualified-struct facts within one decode session.",
      "decision": "Rejected: small-package overhead and hashing/cloning costs."
    },
    {
      "trial": 42,
      "title": "Store fewer redundant header ranges",
      "hypothesis": "Recover expected header bytes from the parent source slice.",
      "decision": "Rejected: extra lookup/bounds work slowed tables."
    },
    {
      "trial": 44,
      "title": "Decode UTF-16 directly from bytes",
      "hypothesis": "Avoid the intermediate u16 vector; retain old malformed-input diagnostics.",
      "decision": "Rejected: no broad throughput gain."
    },
    {
      "trial": 45,
      "title": "Build binary math breadcrumbs lazily",
      "hypothesis": "Delay formatting math error paths until an error needs them.",
      "decision": "Rejected: broader regressions despite a plausible allocation saving."
    },
    {
      "trial": 46,
      "title": "Read vector/rotator components as one block",
      "hypothesis": "Validate a complete math value once, preserving ordinary truncation diagnostics.",
      "decision": "Rejected: no broad gain in the generic helper."
    },
    {
      "trial": 49,
      "title": "Use compact struct-fact cache keys",
      "hypothesis": "Key pure facts by identity and module names instead of cloning/hashing a complete type tree.",
      "decision": "Rejected: cold workloads still regressed."
    },
    {
      "trial": 50,
      "title": "Use a small linear struct-fact cache",
      "hypothesis": "Replace hashing with a bounded contiguous scan.",
      "decision": "Not retained: warm level gain with consistent cold-package regressions."
    },
    {
      "trial": 51,
      "title": "Share immutable type-parameter slices",
      "hypothesis": "Reduce repeated metadata cloning using Arc-backed slices.",
      "decision": "Rejected: cold regressions and a public Rust field-type change."
    },
    {
      "trial": 52,
      "title": "Use thin shared pointers to parameter vectors",
      "hypothesis": "Shrink type nodes further using Arc<Vec<...>>.",
      "decision": "Rejected: severe table slowdown and a public API change."
    },
    {
      "trial": 53,
      "title": "Combine compact paths and header words",
      "hypothesis": "Test the combined result rather than adding independent percentages.",
      "decision": "Not retained: table/corpus gains with level and Blueprint regressions."
    },
    {
      "trial": 54,
      "title": "Prepare vector/rotator recipes per layout",
