      "decision": "Retained math recipes in the combined core1 implementation;24192 guard/bit cases passed."
    },
    {
      "trial": 55,
      "title": "Allocate single-child shared metadata directly",
      "hypothesis": "Avoid an intermediate vector for the overwhelmingly common one-child case.",
      "decision": "Rejected for production: public API change and cold-workload regressions."
    },
    {
      "trial": 56,
      "title": "Use a thin shared single-child node",
      "hypothesis": "Store one child directly behind an Arc; use a vector for longer lists.",
      "decision": "Rejected: severe table slowdown, public API change."
    },
    {
      "trial": 57,
      "title": "Borrow invariant decode context",
      "hypothesis": "Pass a small depth-plus-root-reference value through recursion.",
      "decision": "Rejected alone: smaller arguments did not reliably improve elapsed time."
    },
    {
      "trial": 58,
      "title": "Combine compact context and struct facts",
      "hypothesis": "Reduce argument size while retaining the bounded fact cache.",
      "decision": "Not retained: level gains with Blueprint/small regressions."
