      "trial": 61,
      "title": "Resolve struct identity and module once",
      "hypothesis": "Build all pure facts from one name/module resolution instead of repeated helper lookups.",
      "decision": "Retained single-pass struct facts in core1; frozen helper equivalence cases passed."
